// Mapa campo del Lead -> nombre de columna en el CSV (en minúsculas).
// Se resuelve por NOMBRE de cabecera, no por índice, para ser robusto a los
// cambios de orden y a columnas nuevas (p.ej. "Nivel de Interés", "@ WHATSAPP")
// que han ido apareciendo entre exports.
const CSV_COLUMNS: Record<keyof Lead, string> = {
  id: 'nº',
  status: 'estado',
  interestLevel: 'nivel de interés',
  advisor: 'asesor educativo',
  name: 'nombre',
  channel: 'canal de ingreso',
  digitalId: '# digital',
  phone: 'teléfono',
  university: 'universidad',
  call: 'convocatoria',
  area: 'área de estudio',
  faculty: 'facultad',
  title: 'título de interés',
  lastStudies: 'últimos estudios',
  department: 'departamento',
  city: 'ciudad',
  company: 'empresa',
  email: 'email',
  paymentMethod: 'método de pago',
  reservePaymentDate: 'f. pago reserva',
  closingMonth: 'mes cierre',
  classStart: 'inicio clases',
  discount: 'descuento',
  initialValue: 'valor inicial',
  finalValue: 'valor final',
  coupon: 'pasa cupón',
  directorComment: 'comentario director',
  lastFollowUp: 'f. ult. seguimiento',
  transferred: 'transferido',
  agreementInfo: 'inf. convenio',
  financialInfo: 'inf. financiero',
  homologation: 'homologación',
  createdDate: 'fecha creada',
  lastUpdate: 'última actualización',
};

const parseCsv = (raw: string): Lead[] => {
  const lines = raw.trim().split('\n');
  if (lines.length < 2) return [];

  const headers = lines[0].split(';').map(h => h.trim().toLowerCase());
  const indexOf = (colName: string) => headers.indexOf(colName);

  // Índice de cada campo según la cabecera de ESTE csv.
  const idx = {} as Record<keyof Lead, number>;
  (Object.keys(CSV_COLUMNS) as (keyof Lead)[]).forEach(field => {
    idx[field] = indexOf(CSV_COLUMNS[field]);
  });

  const leads: Lead[] = [];
  for (let i = 1; i < lines.length; i++) {
    const parts = lines[i].split(';');
    if (parts.length < 10) continue;

    const lead = {} as Lead;
    (Object.keys(idx) as (keyof Lead)[]).forEach(field => {
      const at = idx[field];
      lead[field] = (at >= 0 && at < parts.length ? parts[at] : '').trim();
    });
    leads.push(lead);
  }
  return leads;
};

export const parseData = (): Lead[] => parseCsv(rawData);

