export const getCupones = (): Lead[] => parseCsv(cuponesRawData);

export const getKPISummary = (leads: Lead[]) => {
  const total = leads.length;
  const won = leads.filter(l => l.status.toLowerCase() === 'ganado').length;
  const lost = leads.filter(l => l.status.toLowerCase() === 'perdido').length;
  const active = total - won - lost;
  const conversionRate = total > 0 ? ((won / total) * 100).toFixed(1) : '0';
  
  return {
    total,
    totalLeads: total,
    wonLeads: won,
    lostLeads: lost,
    activeLeads: active,
    conversionRate: conversionRate + '%'
  };
};

const groupByCount = (leads: Lead[], keyFn: (l: Lead) => string) => {
  const counts: Record<string, number> = {};
  leads.forEach(l => {
    const key = keyFn(l) || 'Sin Dato';
    counts[key] = (counts[key] || 0) + 1;
  });
  return Object.entries(counts)
    .map(([name, value]) => ({ name, value }))
    .sort((a, b) => b.value - a.value);
};

export const getLeadsByStatus = (leads: Lead[]) => groupByCount(leads, l => l.status);
export const getLeadsByAdvisor = (leads: Lead[]) => groupByCount(leads, l => l.advisor);
export const getLeadsByFaculty = (leads: Lead[]) => groupByCount(leads, l => l.faculty);
export const getLeadsByArea = (leads: Lead[]) => groupByCount(leads, l => l.area);
export const getLeadsByTitle = (leads: Lead[]) => groupByCount(leads, l => l.title);
export const getLeadsByDepartment = (leads: Lead[]) => groupByCount(leads, l => l.department);
export const getLeadsByUniversity = (leads: Lead[]) => groupByCount(leads, l => l.university);

export const getAdvisorStats = (leads: Lead[], ganados: Lead[] = []) => {
  const stats: Record<string, { total: number, won: number, evaluating: number, lost: number }> = {};
  const ensure = (adv: string) => {
    if (!stats[adv]) stats[adv] = { total: 0, won: 0, evaluating: 0, lost: 0 };
    return stats[adv];
  };

  // El dataset de ganados es la fuente autoritativa de "ganados". Algunos de
  // ellos están en el pipeline con OTRO estado (p. ej. Valorando/Cupón), así
  // que no basta con contar los 'ganado' del pipeline.
  const pipelineIds = new Set(leads.map(l => l.digitalId));
  const ganadoIds = new Set(ganados.map(g => g.digitalId));

  leads.forEach(l => {
    const s = ensure(l.advisor || 'Sin Asesor');
    s.total++;

    // Si el lead es realmente un ganado, se contabiliza en la pasada de abajo;
    // aquí no lo clasificamos para no meterlo en "en proceso" ni "perdido".
    if (ganadoIds.has(l.digitalId)) return;

    const status = l.status.toLowerCase();
    if (status === 'ganado') {
      s.won++;
    } else if (status === 'perdido') {
      s.lost++;
    } else {
      s.evaluating++;
    }
  });

  ganados.forEach(g => {
    const s = ensure(g.advisor || 'Sin Asesor');
    s.won++;
    // Los ganados que no están en el pipeline (cierres de convocatorias
    // previas) suman también al total; los que ya están ya se contaron.
    if (!pipelineIds.has(g.digitalId)) s.total++;
  });

  return Object.entries(stats).map(([name, data]) => ({
    name,
    total: data.total,
    won: data.won,
    evaluating: data.evaluating,
    lost: data.lost,
    conversion: data.total > 0 ? ((data.won / data.total) * 100).toFixed(1) : '0.0'
  })).sort((a,b) => b.total - a.total);
};
